namespace Erp.Core.Domain;

/// <summary>
/// Root of every persisted entity. The Id is generated by EF on Add (SQL Server-friendly sequential Guid);
/// audit columns are stamped by the auditing interceptor; RowVersion drives optimistic concurrency.
/// </summary>
public abstract class BaseEntity
{
    public Guid Id { get; set; }

    public DateTimeOffset CreatedAt { get; set; }

    public Guid? CreatedBy { get; set; }

    public DateTimeOffset? UpdatedAt { get; set; }

    public Guid? UpdatedBy { get; set; }

    public byte[] RowVersion { get; set; } = [];
}

/// <summary>Data that belongs to one client account. A global query filter restricts it to the current account.</summary>
public interface IAccountOwned
{
    Guid AccountId { get; }
}

/// <summary>Data that belongs to one business unit. Filtered by the current account and business unit.</summary>
public interface IBusinessUnitOwned : IAccountOwned
{
    Guid BusinessUnitId { get; }
}
